insert into public.quiz_questions
  (type_contenu, slug, ordre, question_fr, question_en, choix_fr, choix_en, bonne_reponse, explication_fr, explication_en)
values
  ('mythe', 'mythe-miengu-esprits-eau-sawa', 1, $q$Dans la croyance sawa, que sont les miengu ?$q$, $q$In Sawa belief, what are the miengu?$q$, $q$["Les ancêtres fondateurs des Duala", "Des génies qui habitent le mont Cameroun", "Des esprits qui vivent dans les rivières et la mer", "Des guérisseurs réunis en confrérie"]$q$::jsonb, $q$["The founding ancestors of the Duala", "Genies who dwell on Mount Cameroon", "Spirits who live in the rivers and the sea", "Healers gathered in a brotherhood"]$q$::jsonb, 2, $q$Les miengu (jengu au singulier chez les Duala, liengu chez les Bakweri) sont des esprits de l'eau. Pendant des siècles, ils ont été au cœur de la pêche, de la guérison et de l'initiation.$q$, $q$The miengu (jengu in the singular for the Duala, liengu for the Bakweri) are water spirits. For centuries they were at the heart of fishing, healing and initiation.$q$),
  ('mythe', 'mythe-miengu-esprits-eau-sawa', 2, $q$Dans le rite bakweri du liengu la ndiva, qu'est-ce qui prouve que l'eau a appelé la jeune fille ?$q$, $q$In the Bakweri rite of liengu la ndiva, what proves that the water has called the girl?$q$, $q$["Elle comprend la langue secrète liengu qu'on lui parle", "Elle attrape un crabe dans le ruisseau", "Elle voit une sirène trois nuits de suite", "Elle chante un chant liengu sans l'avoir appris"]$q$::jsonb, $q$["She understands the secret liengu language spoken to her", "She catches a crab in the stream", "She sees a mermaid three nights in a row", "She sings a liengu song she never learned"]$q$::jsonb, 0, $q$Une femme initiée lui parle dans la langue secrète liengu : si elle montre qu'elle comprend, le doute n'est plus permis. Suivent la réclusion, puis l'entrée dans l'eau profonde.$q$, $q$An initiated woman speaks to her in the secret liengu language: if she shows she understands, there is no more doubt. Then come seclusion and the plunge into deep water.$q$),
  ('mythe', 'mythe-miengu-esprits-eau-sawa', 3, $q$Dans le mythe bakweri du feu, pourquoi Moto devient-il l'Homme ?$q$, $q$In the Bakweri myth of the fire, why does Moto become Man?$q$, $q$["Il a gagné une course jusqu'au village", "Il a été choisi par la dame de la mer", "Il est rentré des champs le premier", "Son feu de grosses bûches brûlait encore le soir"]$q$::jsonb, $q$["He won a race back to the village", "He was chosen by the lady of the sea", "He came home from the fields first", "His fire of big logs was still burning at nightfall"]$q$::jsonb, 3, $q$Moto, plus rusé, avait disposé de grosses bûches : le soir, son feu brûlait encore. Il resta au village, Ewaki devint le singe et Mojili, chassé dans l'eau, un esprit de l'eau.$q$, $q$Moto, the craftiest, had laid big logs: at nightfall his fire was still burning. He stayed in the village; Ewaki became the Ape and Mojili, driven into the water, a water spirit.$q$),
  ('mythe', 'mythe-miengu-esprits-eau-sawa', 4, $q$Selon l'historien de l'art Henry Drewal, d'où vient l'image la plus célèbre de Mami Wata ?$q$, $q$According to art historian Henry Drewal, where does the most famous image of Mami Wata come from?$q$, $q$["D'une statue de jengu sculptée à Douala", "D'une affiche de cirque imprimée à Hambourg", "D'une gravure de missionnaire baptiste", "D'un timbre de la colonie allemande"]$q$::jsonb, $q$["A jengu statue carved in Douala", "A circus poster printed in Hamburg", "A Baptist missionary's engraving", "A stamp from the German colony"]$q$::jsonb, 1, $q$Cette femme aux serpents vient d'une affiche de cirque imprimée à Hambourg dans les années 1880. Drewal distingue Mami Wata, figure des ports et de l'argent, des esprits des eaux locaux comme les miengu.$q$, $q$This woman with snakes comes from a circus poster printed in Hamburg in the 1880s. Drewal separates Mami Wata, a figure of ports and money, from local water spirits such as the miengu.$q$),
  ('mythe', 'mythe-miengu-esprits-eau-sawa', 5, $q$Au Ngondo, que fait le prêtre le premier dimanche de décembre ?$q$, $q$At the Ngondo, what does the priest do on the first Sunday of December?$q$, $q$["Il lit l'avenir dans la course de pirogues", "Il bénit la foule depuis l'île de Jebale", "Il allume un feu sacré sur la berge", "Il plonge dans le Wouri avec les vœux du peuple"]$q$::jsonb, $q$["He reads the future in the canoe race", "He blesses the crowd from Jebale island", "He lights a sacred fire on the riverbank", "He dives into the Wouri with the people's wishes"]$q$::jsonb, 3, $q$Il plonge avec un vase contenant les vœux de la communauté et rapporte un message des esprits. Ce rite a été inscrit au patrimoine immatériel de l'UNESCO le 4 décembre 2024.$q$, $q$He dives with a vessel holding the community's wishes and brings back a message from the spirits. The rite was inscribed on UNESCO's intangible heritage list on 4 December 2024.$q$),
  ('mythe', 'mythe-nchare-yen-bamoun', 1, $q$Au couronnement décrit par le roi Njoya, que fait le peuple quand Njikumjue l'appelle ?$q$, $q$At the enthronement described by King Njoya, what do the people do when Njikumjue calls them?$q$, $q$["Il répond d'une seule voix", "Il l'acclame comme nouveau roi", "Il se tait, puis répond au nouveau roi", "Il appelle les Kom à trancher"]$q$::jsonb, $q$["They answer with one voice", "They hail him as the new king", "They stay silent, then answer the new king", "They call on the Kom to decide"]$q$::jsonb, 2, $q$Les Pamom ne répondent pas à Njikumjue, puis répondent tous au nouveau roi. Le rite le rappelle : le roi n'est pas le plus rapide, c'est celui à qui le peuple répond.$q$, $q$The Pamom do not answer Njikumjue, then all answer the new king. The rite is a reminder: the king is not the fastest runner, he is the one the people answer.$q$),
  ('mythe', 'mythe-nchare-yen-bamoun', 2, $q$Dans la légende de la course, comment Nchare devance-t-il son frère Koumjouom ?$q$, $q$In the legend of the race, how does Nchare get ahead of his brother Koumjouom?$q$, $q$["Il part avant le signal de Njimongha", "Sa sœur Mfom s'est assise sur le pagne de Koumjouom", "Koumjouom se blesse au pied en partant", "Il court plus vite que tous les prétendants"]$q$::jsonb, $q$["He sets off before Njimongha's signal", "His sister Mfom sat on a fold of Koumjouom's wrapper", "Koumjouom hurts his foot at the start", "He runs faster than all the other claimants"]$q$::jsonb, 1, $q$Selon la légende, Mfom s'assit sur un pan du pagne de Koumjouom, retenu au départ. Le livre de Njoya dit d'ailleurs que Nchare ne savait pas courir : c'est la ruse des siens qui le fit roi.$q$, $q$According to the legend, Mfom sat on a fold of Koumjouom's wrapper, holding him back at the start. Njoya's book even says Nchare could not run: his people's cunning made him king.$q$),
  ('mythe', 'mythe-nchare-yen-bamoun', 3, $q$Selon la tradition bamoun, que se passe-t-il à Njimom, sur les sept pierres ?$q$, $q$In Bamum tradition, what happens at Njimom, on the seven stones?$q$, $q$["Le roi de Rifum bénit Nchare au bord du lac", "Nchare et ses frères se partagent trois royaumes", "Les Pambèn cèdent à Nchare leur capitale", "Nchare et sept compagnons proclament l'État bamoun"]$q$::jsonb, $q$["The king of Rifum blesses Nchare by the lake", "Nchare and his siblings share out three kingdoms", "The Pambèn hand their capital over to Nchare", "Nchare and seven companions proclaim the Bamum State"]$q$::jsonb, 3, $q$Assis avec ses sept compagnons, les Kom, Nchare proclame le pacte : « L'État bamum est né et Nshare en est le roi. » Les Kom deviennent les gardiens de cette loi fondatrice.$q$, $q$Seated with his seven companions, the Kom, Nchare proclaims the pact: "The Bamum State is born and Nshare is its king." The Kom become the guardians of this founding law.$q$),
  ('mythe', 'mythe-nchare-yen-bamoun', 4, $q$Comment le roi Njoya a-t-il calculé la date de 1394 pour le règne de Nchare ?$q$, $q$How did King Njoya work out the date of 1394 for Nchare's reign?$q$, $q$["En comptant à rebours les Nguon de chaque règne", "En lisant une chronique arabe du Bornou", "En la recevant des missionnaires de Bâle", "En comptant les sept pierres de Njimom"]$q$::jsonb, $q$["By counting back each reign's Nguon", "By reading an Arabic chronicle from Bornu", "By receiving it from the Basel missionaries", "By counting the seven stones of Njimom"]$q$::jsonb, 0, $q$Partant de 1902, il a remonté les règnes en comptant les Nguon de chacun. Mais la date est débattue : Martin la jugeait « pure fantaisie », Tardits place la fondation au XVIIe siècle.$q$, $q$Starting from 1902, he went back reign by reign, counting each king's Nguon. But the date is disputed: Martin called it "pure fantasy", and Tardits places the founding in the 17th century.$q$),
  ('mythe', 'mythe-nchare-yen-bamoun', 5, $q$Lors du Nguon, inscrit à l'UNESCO en 2023, que se passe-t-il pour le roi ?$q$, $q$During the Nguon, inscribed by UNESCO in 2023, what happens to the king?$q$, $q$["Il reçoit la dépouille d'une panthère", "Il retourne se faire bénir à Rifum", "Il est jugé en public par son peuple", "Il s'assoit sur les sept pierres de Njimom"]$q$::jsonb, $q$["He receives the skin of a panther", "He goes back to Rifum to be blessed", "He is judged in public by his people", "He sits on the seven stones of Njimom"]$q$::jsonb, 2, $q$Les chefs rituels recueillent ce que le peuple pense du roi, puis le jugent devant la foule. En 2024, le jeune roi s'est vu reprocher le délabrement des biens du royaume.$q$, $q$The ritual chiefs gather what the people think of the king, then judge him before the crowd. In 2024, the young king was criticised for the dilapidated state of the kingdom's property.$q$),
  ('mythe', 'mythe-ngan-medza-beti', 1, $q$Pourquoi les historiens doutent-ils qu'Ousman dan Fodio ait chassé les premiers Beti ?$q$, $q$Why do historians doubt that Usman dan Fodio drove out the first Beti?$q$, $q$["Son jihad commença seulement en 1875", "Des traversées auraient eu lieu plus d'un siècle avant son jihad", "Les Beti venaient du sud, pas du nord", "Les Beti n'ont jamais traversé la Sanaga"]$q$::jsonb, $q$["His jihad only began in 1875", "Some crossings may have happened over a century before his jihad", "The Beti came from the south, not the north", "The Beti never crossed the Sanaga"]$q$::jsonb, 1, $q$Le jihad commence en 1805, mais Laburthe-Tolra place la traversée des Bënë vers 1680-1685. Le nom de dan Fodio a pu se poser sur un souvenir bien plus ancien.$q$, $q$The jihad began in 1805, but Laburthe-Tolra places the Bënë crossing around 1680 to 1685. Dan Fodio's name may have settled on a far older memory.$q$),
  ('mythe', 'mythe-ngan-medza-beti', 2, $q$Selon la légende, sur quoi le peuple beti traversa-t-il le Yom, la Sanaga ?$q$, $q$According to the legend, on what did the Beti people cross the Yom, the Sanaga?$q$, $q$["Une flotte de pirogues", "Un pont de lianes", "Un radeau construit par les anciens", "Le dos d'un serpent immense"]$q$::jsonb, $q$["A fleet of canoes", "A bridge of lianas", "A raft built by the elders", "The back of an immense serpent"]$q$::jsonb, 3, $q$Selon la tradition, le serpent Ngan Medza se coucha d'une rive à l'autre. Le peuple le prit d'abord pour un gros tronc d'arbre : on ne nommait pas le serpent, pour ne pas faire peur.$q$, $q$According to tradition, the serpent Ngan Medza lay down from one bank to the other. At first the people took it for a big tree trunk: the serpent was not named, so as not to cause fear.$q$),
  ('mythe', 'mythe-ngan-medza-beti', 3, $q$Dans les versions beti, qu'est-ce qui fit disparaître le pont vivant ?$q$, $q$In the Beti versions, what made the living bridge vanish?$q$, $q$["L'interdit brisé : une lance ou une torche le blessa", "Une crue soudaine emporta le pont", "Le poids des vieillards le fit céder", "Le serpent s'en alla au lever du soleil"]$q$::jsonb, $q$["A broken taboo: a spear or a torch wounded it", "A sudden flood swept the bridge away", "The weight of the elders made it give way", "The serpent left at sunrise"]$q$::jsonb, 0, $q$Un interdit protégeait le pont : pas de pointe, rien de tranchant. Une lance plantée ou une torche tombée réveilla le serpent, et ceux restés sur la rive nord furent séparés des autres.$q$, $q$A taboo protected the bridge: no points, nothing sharp. A spear thrust in or a fallen torch woke the serpent, and those still on the north bank were cut off from the rest.$q$),
  ('mythe', 'mythe-ngan-medza-beti', 4, $q$Dans la version manguissa, comment naît le python qui sert de pont ?$q$, $q$In the Manguissa version, how is the python that serves as a bridge born?$q$, $q$["Il sort d'un œuf trouvé sur la rive", "Il est envoyé par le chef des Mvele", "Un arc-en-ciel surgi du fleuve devient python", "Il descend des montagnes de l'Adamaoua"]$q$::jsonb, $q$["It hatches from an egg found on the bank", "It is sent by the chief of the Mvele", "A rainbow rising from the river becomes a python", "It comes down from the Adamawa mountains"]$q$::jsonb, 2, $q$Selon la tradition manguissa rapportée par Laburthe-Tolra, l'ancêtre Aso Abanda frappa l'eau de son bâton magique : un arc-en-ciel surgit et devint sur l'eau le python, le mvom.$q$, $q$In the Manguissa tradition reported by Laburthe-Tolra, the ancestor Aso Abanda struck the water with his magic staff: a rainbow rose and became, on the water, the python, the mvom.$q$),
  ('mythe', 'mythe-ngan-medza-beti', 5, $q$Selon Laburthe-Tolra, que désignait aussi « ngan medza » chez les anciens Beti ?$q$, $q$According to Laburthe-Tolra, what else did "ngan medza" mean among the old Beti?$q$, $q$["Le nom ancien du fleuve Sanaga", "Une puissance protectrice de l'homme puissant", "Un totem dont descendaient tous les Beti", "Le surnom du passeur Nnë Bodo"]$q$::jsonb, $q$["The old name of the Sanaga River", "A protective power of a powerful man", "A totem all Beti descended from", "The nickname of the ferryman Nnë Bodo"]$q$::jsonb, 1, $q$Tout Beti puissant était censé posséder « son propre ngan medza », un python invisible qui le protégeait. Laburthe-Tolra traduit : « ruine pour (tout) charme (adverse) ».$q$, $q$Every powerful Beti was supposed to possess "his own ngan medza", an invisible python that protected him. Laburthe-Tolra translates it: "ruin for (every) (hostile) charm".$q$),
  ('mythe', 'mythe-ngog-lituba-bassa', 1, $q$Que disent les Basaa, les Elog-Mpoo et les Bati du rocher de Ngog Lituba ?$q$, $q$What do the Basaa, Elog-Mpoo and Bati say about the rock of Ngog Lituba?$q$, $q$["Que leurs premiers ancêtres en sont sortis", "Qu'il fut bâti par leurs premiers rois", "Qu'un serpent y garde leurs morts", "Qu'il marque la frontière avec les Duala"]$q$::jsonb, $q$["That their first ancestors came out of it", "That it was built by their first kings", "That a serpent guards their dead inside it", "That it marks the border with the Duala"]$q$::jsonb, 0, $q$Tous se disent « enfants du rocher percé » : selon la tradition, les premiers ancêtres sont sortis de sa grotte. Ngog veut dire le rocher, lituba le trou, ou le refuge selon une lecture mpoo.$q$, $q$All call themselves "children of the pierced rock": according to tradition, the first ancestors came out of its cave. Ngog means rock, lituba the hole, or the refuge in a Mpoo reading.$q$),
  ('mythe', 'mythe-ngog-lituba-bassa', 2, $q$Dans le récit recueilli par Mboui, pourquoi Mban devient-il le premier chef ?$q$, $q$In the story collected by Mboui, why does Mban become the first chief?$q$, $q$["Il est le fils aîné de Ngog", "Il est le plus fort des neuf hommes", "Il a osé chercher ses origines", "Il a sauvé le groupe d'un ennemi"]$q$::jsonb, $q$["He is Ngog's eldest son", "He is the strongest of the nine men", "He dared to seek out his origins", "He saved the group from an enemy"]$q$::jsonb, 2, $q$L'aîné, c'était Mbog. Mban fut choisi parce qu'il osa demander qui étaient ses pères et ses mères. C'est une femme, Ki Wom, qui le consacra en versant l'eau d'une calebasse sur sa tête.$q$, $q$The eldest was Mbog. Mban was chosen because he dared to ask who his fathers and mothers were. A woman, Ki Wom, consecrated him by pouring water from a calabash over his head.$q$),
  ('mythe', 'mythe-ngog-lituba-bassa', 3, $q$Quelles sont les trois portes que Mban franchit dans le rocher ?$q$, $q$What are the three doors Mban passes through inside the rock?$q$, $q$["La terre, l'eau et le feu", "La peur, la faim et la mort", "Le ciel, la forêt et le fleuve", "La force, la nuit et le jour"]$q$::jsonb, $q$["Earth, water and fire", "Fear, hunger and death", "Sky, forest and river", "Strength, night and day"]$q$::jsonb, 3, $q$Ngui, la force, lui rend la vue ; U, la nuit, lui donne le pouvoir de transformer ; Kel, le jour, lui ouvre « les entrepôts de la vie ». C'est le récit d'une initiation.$q$, $q$Ngui, strength, restores his sight; U, night, gives him the power to transform; Kel, day, opens "the storehouses of life" to him. It is the story of an initiation.$q$),
  ('mythe', 'mythe-ngog-lituba-bassa', 4, $q$Dans la version la plus répandue, qu'est-ce qui sauve les ancêtres réfugiés dans la grotte ?$q$, $q$In the most widespread version, what saves the ancestors hiding in the cave?$q$, $q$["Un serpent couché devant l'entrée", "Une araignée qui tisse sa toile à l'entrée", "Un éboulement qui ferme la grotte", "Un brouillard envoyé par Nyambe"]$q$::jsonb, $q$["A serpent lying across the entrance", "A spider weaving its web across the entrance", "A rockfall that seals the cave", "A mist sent by Nyambe"]$q$::jsonb, 1, $q$Voyant la toile intacte, les poursuivants crurent que personne n'était entré. Cette version, absente du récit de Mboui, éclaire le second nom du lieu : le rocher du refuge.$q$, $q$Seeing the web unbroken, the pursuers thought no one had gone in. This version, absent from Mboui's story, sheds light on the place's second name: the rock of refuge.$q$),
  ('mythe', 'mythe-ngog-lituba-bassa', 5, $q$Que dit le récit de l'idée selon laquelle les Basaa viendraient d'Égypte ?$q$, $q$What does the story say about the idea that the Basaa came from Egypt?$q$, $q$["Que des fouilles au rocher l'ont prouvée", "Que les missionnaires l'ont inventée", "Que c'est un récit d'identité, sans preuve reconnue", "Que Mboui l'a recueillie en 1967"]$q$::jsonb, $q$["That digs at the rock have proved it", "That the missionaries invented it", "That it is a story of identity, with no recognised proof", "That Mboui recorded it in 1967"]$q$::jsonb, 2, $q$Aucune preuve archéologique, linguistique ou génétique reconnue ne la démontre : le basaa est une langue bantoue. C'est un récit d'identité moderne, encore discuté, pas un fait établi.$q$, $q$No recognised archaeological, linguistic or genetic evidence shows it: Basaa is a Bantu language. It is a modern story of identity, still argued over, not an established fact.$q$),
  ('mythe', 'mythe-sao-geants-kotoko', 1, $q$Selon la tradition orale de la plaine du lac Tchad, qui étaient les Sao ?$q$, $q$According to the oral tradition of the Lake Chad plain, who were the Sao?$q$, $q$["Des esprits qui vivaient dans le lac", "Des cavaliers venus du Bornou", "Des nains habitant les marais", "Des géants hauts comme des palmiers"]$q$::jsonb, $q$["Spirits who lived in the lake", "Horsemen who came from Bornu", "Dwarfs who lived in the marshes", "Giants as tall as palm trees"]$q$::jsonb, 3, $q$La légende fait des Sao des géants aux arcs taillés dans des palmiers entiers. Les Kotoko d'aujourd'hui se disent tous leurs descendants.$q$, $q$The legend makes the Sao giants whose bows were cut from whole palm trees. Today's Kotoko all claim to be their descendants.$q$),
  ('mythe', 'mythe-sao-geants-kotoko', 2, $q$Que contenaient les grandes jarres enfouies dans les buttes dites sao ?$q$, $q$What did the great jars buried in the so-called Sao mounds contain?$q$, $q$["Des défunts : c'étaient des tombes", "Des réserves de mil pour la saison sèche", "Des bronzes offerts aux rois du Bornou", "De l'eau sacrée pour les cérémonies"]$q$::jsonb, $q$["The dead: they were tombs", "Millet stores for the dry season", "Bronzes offered to the kings of Bornu", "Sacred water for ceremonies"]$q$::jsonb, 0, $q$Les fouilles montrent des défunts déposés dans de grandes jarres, parfois fermées par une seconde jarre retournée. La légende le disait : ils enterraient leurs morts dans des poteries.$q$, $q$Excavations show the dead laid in large jars, sometimes closed by a second, upturned jar. The legend said so: they buried their dead in pots.$q$),
  ('mythe', 'mythe-sao-geants-kotoko', 3, $q$Selon le linguiste Henry Tourneux, d'où viendrait le nom « Sao » ?$q$, $q$According to linguist Henry Tourneux, where might the name "Sao" come from?$q$, $q$["D'un roi fondateur appelé Sao", "D'un mot arabe qui veut dire « géant »", "De l'enceinte d'épines, puis de la muraille des cités", "Du nom ancien du fleuve Chari"]$q$::jsonb, $q$["A founding king called Sao", "An Arabic word meaning 'giant'", "The thorn enclosure, then the wall of the towns", "The old name of the Chari River"]$q$::jsonb, 2, $q$Les voisins auraient nommé ces gens d'après leur clôture d'épineux, puis le mot serait resté attaché à la muraille. Pour Tourneux, « Sao » ne désigne donc pas un groupe ethnique précis.$q$, $q$Neighbours may have named these people after their thorn fence, and the word then stayed attached to the earthen wall. For Tourneux, "Sao" is not the name of one ethnic group.$q$),
  ('mythe', 'mythe-sao-geants-kotoko', 4, $q$Selon la liste royale du Bornou lue par Barth, que firent les Sao au XIVe siècle ?$q$, $q$According to the Bornu king list read by Barth, what did the Sao do in the 14th century?$q$, $q$["Ils se convertirent tous à l'islam", "Ils tuèrent quatre rois du Bornou en quelques années", "Ils s'enfuirent dans les îles du lac", "Ils payèrent tribut au sultan du Kanem"]$q$::jsonb, $q$["They all converted to Islam", "They killed four kings of Bornu within a few years", "They fled to the islands of the lake", "They paid tribute to the sultan of Kanem"]$q$::jsonb, 1, $q$Les Sao tuèrent quatre rois du Bornou l'un après l'autre. Au XVIe siècle, le maï Idris Alauma leur fit une dure guerre de conquête, racontée par son chroniqueur Ibn Furtu.$q$, $q$The Sao killed four kings of Bornu, one after another. In the 16th century, Mai Idris Alauma waged a harsh war of conquest against them, told by his chronicler Ibn Furtu.$q$),
  ('mythe', 'mythe-sao-geants-kotoko', 5, $q$Dans les récits venus du Kanem et du Bornou, que deviennent les géants sao ?$q$, $q$In the stories from Kanem and Bornu, what do the Sao giants become?$q$, $q$["Des ogres païens qu'il fallait abattre", "Des ancêtres de lumière qui s'éclairent à l'or", "Des alliés venus défendre le sultan", "Des pêcheurs paisibles devenus musulmans"]$q$::jsonb, $q$["Pagan ogres who had to be cut down", "Ancestors of light who see by the glow of gold", "Allies who came to defend the sultan", "Peaceful fishermen turned Muslim"]$q$::jsonb, 0, $q$Chez les vainqueurs, les Sao sont des ogres gloutons et païens, et le mythe justifie la guerre. Chez les Kotoko, les mêmes géants sont des fondateurs dont on hérite la terre.$q$, $q$For the victors, the Sao are greedy, pagan ogres, and the myth justifies the war. For the Kotoko, the same giants are founders whose heirs hold the land.$q$);
insert into public.quiz_questions
  (type_contenu, slug, ordre, question_fr, question_en, choix_fr, choix_en, bonne_reponse, explication_fr, explication_en)
values
  ('mythe', 'mythe-zamba-evu-beti', 1, $q$Dans le mythe beti, quels deux interdits Zamba laisse-t-il avant de partir en voyage ?$q$, $q$In the Beti myth, what two prohibitions does Zamba leave before setting off on his journey?$q$, $q$["Ne pas chasser la nuit, ne pas boire l'eau du marécage", "Ne pas enterrer celui qui dort le sommeil mâle, ne pas prendre l'evu", "Ne pas quitter le village, ne pas parler aux étrangers", "Ne pas couper le grand arbre, ne pas manger le gibier cru"]$q$::jsonb, $q$["Do not hunt at night, do not drink the swamp water", "Do not bury one who sleeps the male sleep, do not take the evu", "Do not leave the village, do not speak to strangers", "Do not fell the great tree, do not eat raw game"]$q$::jsonb, 1, $q$Selon le mythe, Zamba dit de ne pas enterrer celui qui tombe dans le nnom oyo, le sommeil mâle, et de ne pas prendre l'evu, la bête de la forêt. Les deux paroles seront brisées.$q$, $q$In the myth, Zamba says not to bury anyone who falls into the nnom oyo, the male sleep, and not to take the evu, the beast of the forest. Both words will be broken.$q$),
  ('mythe', 'mythe-zamba-evu-beti', 2, $q$Dans une version evuzok recueillie par Mallart-Guimerà, qui est l'evu ?$q$, $q$In an Evuzok version collected by Mallart-Guimerà, who is the evu?$q$, $q$["Le chasseur du léopard, chassé du village", "Un ancêtre puni pour avoir volé du gibier", "L'esprit d'une épouse venue d'un autre clan", "Un fils de Zamba, laissé sans femme ni biens"]$q$::jsonb, $q$["The leopard's hunter, driven from the village", "An ancestor punished for stealing game", "The spirit of a wife from another clan", "A son of Zamba, left without a wife or goods"]$q$::jsonb, 3, $q$Dans cette variante, Zamba donne une femme et des richesses à ses fils Homme, Gorille et Chimpanzé, mais rien à l'evu, caché dans un arbre creux. Le récit dit ainsi d'où vient sa faim.$q$, $q$In this variant, Zamba gives a wife and riches to his sons Man, Gorilla and Chimpanzee, but nothing to the evu, hidden in a hollow tree. The tale thus tells where its hunger comes from.$q$),
  ('mythe', 'mythe-zamba-evu-beti', 3, $q$Selon le mythe, comment la femme ramène-t-elle l'evu au village ?$q$, $q$According to the myth, how does the woman bring the evu back to the village?$q$, $q$["Il entre dans son ventre au bord de l'eau", "Elle le porte dans le grand panier", "Elle le cache au fond d'une calebasse", "Il la suit en sautant dans la nuit"]$q$::jsonb, $q$["It enters her belly at the water's edge", "She carries it in the big basket", "She hides it at the bottom of a gourd", "It follows her, hopping through the night"]$q$::jsonb, 0, $q$D'après la légende, l'evu refuse le grand panier, le petit panier et le dos, puis entre dans le ventre de la femme. L'anthropologue André Mary y voit « une naissance à l'envers ».$q$, $q$According to the legend, the evu refuses the big basket, the small basket and her back, then enters the woman's belly. The anthropologist André Mary calls it "a birth in reverse".$q$),
  ('mythe', 'mythe-zamba-evu-beti', 4, $q$À son retour, pourquoi Zamba ne peut-il pas ressusciter sa fille ?$q$, $q$When he returns, why can Zamba not bring his daughter back to life?$q$, $q$["Elle est déjà montée au ciel sans lui", "Il revient privé de ses pouvoirs", "Sa mère l'a enterrée pendant son absence", "Elle a mangé le gibier défendu"]$q$::jsonb, $q$["She has already gone up to the sky without him", "He comes back stripped of his powers", "Her mother buried her while he was away", "She ate the forbidden game"]$q$::jsonb, 2, $q$Selon le mythe, la fille était tombée dans le sommeil mâle. Zamba tardant, la mère l'enterra : « Mais je l'ai enterrée... ». Le sommeil devint la mort, et Zamba partit pour de bon.$q$, $q$In the myth, the daughter had fallen into the male sleep. As Zamba was late, her mother buried her: "But I have buried her..." Sleep became death, and Zamba left for good.$q$),
  ('mythe', 'mythe-zamba-evu-beti', 5, $q$Chez les Evuzok, que dit l'oncle maternel à l'enfant dont il éveille l'evu ?$q$, $q$Among the Evuzok, what does the maternal uncle tell the child whose evu he awakens?$q$, $q$["Donne aux gens de la nourriture et aime les hommes", "Garde ta force cachée et ne la montre à personne", "Chasse pour ton clan et ne partage qu'avec lui", "Ne retourne jamais au bord du marécage"]$q$::jsonb, $q$["Give people food and love humankind", "Keep your force hidden and show it to no one", "Hunt for your clan and share only with it", "Never go back to the edge of the swamp"]$q$::jsonb, 0, $q$Mallart-Guimerà décrit ce rite : l'oncle oriente l'evu de prospérité vers le bien. C'est l'inverse de l'evu du mythe, qui prenait la nourriture du village : le rite lui apprend à nourrir.$q$, $q$Mallart-Guimerà describes this rite: the uncle directs the evu of prosperity towards good. It is the opposite of the myth's evu, which took the village's food: the rite teaches it to feed.$q$),
  ('mythe', 'mythe-ngam-araignee-beti', 1, $q$Chez les Ewondo, comment le devin lit-il l'avenir avec la mygale ?$q$, $q$Among the Ewondo, how does the diviner read the future with the mygale?$q$, $q$["Il écoute la mygale bouger dans son trou", "Il compte les fils de sa toile au matin", "Il regarde où elle a déplacé les bâtonnets la nuit", "Il observe la direction qu'elle prend en sortant"]$q$::jsonb, $q$["He listens to the mygale moving in its hole", "He counts the threads of its web in the morning", "He looks at where it moved the sticks overnight", "He watches which way it goes when it comes out"]$q$::jsonb, 2, $q$L'abbé Tsala le décrit : le devin pose des bâtonnets, les avol, autour du trou et les couvre de feuilles. La nuit, la mygale les bouscule ; au matin, il lit l'avenir dans leur désordre.$q$, $q$Father Tsala describes it: the diviner lays sticks, the avol, around the hole and covers them with leaves. At night the mygale knocks them about; in the morning he reads the future in the disorder.$q$),
  ('mythe', 'mythe-ngam-araignee-beti', 2, $q$Selon l'abbé Tsala, que veut dire Ntondobe, l'un des noms de Dieu chez les Beti ?$q$, $q$According to Father Tsala, what does Ntondobe, one of the Beti names for God, mean?$q$, $q$["Soutien des hommes, comme le tuteur de l'igname", "Celui qui chasse chaque jour pour les hommes", "Le maître du carrefour des neuf chemins", "Celui qui habite au fond de la terre"]$q$::jsonb, $q$["Support of people, like the stake of a yam vine", "He who hunts every day for people", "The master of the crossroads of nine paths", "He who dwells deep beneath the earth"]$q$::jsonb, 0, $q$Tsala décompose ntondo bod, « soutien des hommes » : le ntondo est le tuteur planté près d'une plante grimpante. Dieu tient l'homme debout, d'où la question : pourquoi l'homme souffre-t-il ?$q$, $q$Tsala breaks down ntondo bod, "support of people": the ntondo is the stake planted beside a climbing plant. God keeps people upright, hence the question: why do people suffer?$q$),
  ('mythe', 'mythe-ngam-araignee-beti', 3, $q$Dans la version chantée par Vincent Mesi à Tala en 1963, quelle sentence Dieu prononce-t-il contre l'araignée ?$q$, $q$In the version sung by Vincent Mesi at Tala in 1963, what sentence does God pass on the spider?$q$, $q$["Elle ne quittera plus jamais sa toile", "Elle perdra la parole devant les hommes", "Elle sera chassée du ciel pour toujours", "Elle mourra suspendue en l'air, jamais par terre"]$q$::jsonb, $q$["She will never again leave her web", "She will lose her speech before people", "She will be driven from the sky forever", "She will die hanging in the air, never on the ground"]$q$::jsonb, 3, $q$Selon la légende, Dieu se tait puis la condamne à ne mourir que suspendue en l'air. Privée de tombe pour sa bravade, l'araignée morte reste pendue à sa toile.$q$, $q$According to the legend, God falls silent, then condemns her to die only hanging in the air. Denied a grave for her bravado, the dead spider stays hanging from its web.$q$),
  ('mythe', 'mythe-ngam-araignee-beti', 4, $q$Dans la version d'Elisabeth Belomo (2017), pourquoi l'araignée devient-elle Ngam, la voyante ?$q$, $q$In Elisabeth Belomo's version (2017), why does the spider become Ngam, the seer?$q$, $q$["Elle a tissé la plus grande toile du monde", "Elle est la seule créature à avoir rencontré Dieu", "Le varan lui a confié tous ses secrets", "Elle a gagné son procès contre le varan"]$q$::jsonb, $q$["She wove the largest web in the world", "She is the only creature to have met God", "The monitor lizard entrusted her with all his secrets", "She won her trial against the monitor lizard"]$q$::jsonb, 1, $q$D'après la légende, après dix ans de voyage, Ntondobe la condamne à vivre sous terre. Mais, seule créature à avoir rencontré le Tout-Puissant, elle est associée à la clairvoyance et renommée Ngam.$q$, $q$According to the legend, after a ten-year journey, Ntondobe condemns her to live underground. But as the only creature to have met the Almighty, she is linked to clairvoyance and renamed Ngam.$q$),
  ('mythe', 'mythe-ngam-araignee-beti', 5, $q$Selon un autre récit rapporté par Tsala, pourquoi a-t-on cru que les araignées abritaient des génies ?$q$, $q$According to another story reported by Tsala, why did people come to believe spiders housed spirits?$q$, $q$["Une mygale a guéri un enfant aveugle", "Une araignée a annoncé la venue des ennemis", "Un génie devenu araignée a caché un fugitif sous sa toile", "Un devin a vu un génie sortir du trou"]$q$::jsonb, $q$["A mygale healed a blind child", "A spider warned of the enemies' approach", "A spirit turned spider hid a fugitive behind its web", "A diviner saw a spirit come out of the hole"]$q$::jsonb, 2, $q$Selon cette tradition, un homme poursuivi se cacha dans un arbre creux. Son génie gardien, devenu araignée, tissa sa toile à l'entrée. Les ennemis passèrent, et l'on se mit à consulter la mygale.$q$, $q$According to this tradition, a hunted man hid in a hollow tree. His guardian spirit, turned spider, spun its web across the opening. The enemies passed by, and people began to consult the mygale.$q$),
  ('mythe', 'mythe-enfants-ombono-mbam', 1, $q$Quand on demande aux peuples du Mbam qui était Ombono, que se passe-t-il ?$q$, $q$When you ask the peoples of the Mbam who Ombono was, what happens?$q$, $q$["Ils renvoient tous au même chasseur", "Ils refusent de prononcer son nom", "Ils désignent un roi venu de Foumban", "Chaque peuple donne une réponse différente"]$q$::jsonb, $q$["They all point to the same hunter", "They refuse to speak the name", "They name a king who came from Foumban", "Each people gives a different answer"]$q$::jsonb, 3, $q$Pour les uns, Ombono est un chasseur ; pour d'autres, une fille unique, une mère de onze enfants, un père. Le griot ne choisit pas : c'est l'ensemble de ces voix qui fait le mythe.$q$, $q$For some, Ombono is a hunter; for others, an only daughter, a mother of eleven, a father. The griot does not choose: it is all these voices together that make the myth.$q$),
  ('mythe', 'mythe-enfants-ombono-mbam', 2, $q$Dans la version maande, comment Ombono règle-t-il la dot de son épouse banen, Ekiíkí ?$q$, $q$In the Maande version, how does Ombono settle the bride price for his Banen wife, Ekiíkí?$q$, $q$["Avec des têtes de bétail et des ignames", "Il envoie son premier fils, Benenyi, chez les Banen", "Il chasse un an pour la famille d'Ekiíkí", "Il offre aux Banen la savane d'Osimbe"]$q$::jsonb, $q$["With heads of livestock and yams", "He sends his first son, Benenyi, to the Banen", "He hunts for Ekiíkí's family for a year", "He gives the Banen the savanna of Osimbe"]$q$::jsonb, 1, $q$Selon la tradition maande, Ombono n'avait pas doté Ekiíkí. Leur premier-né, Benenyi, fut envoyé chez ses oncles banen à la place de la dot. La dette devint un lien de parenté.$q$, $q$According to Maande tradition, Ombono had not paid Ekiíkí's bride price. Their firstborn, Benenyi, was sent to his Banen uncles in its place. The debt became a bond of kinship.$q$),
  ('mythe', 'mythe-enfants-ombono-mbam', 3, $q$Dans la version gunu, qui est Ombono ?$q$, $q$In the Gunu version, who is Ombono?$q$, $q$["La fille unique de Kamba, un esclave en fuite", "Le chef de guerre qui condamna Kamba", "Un chasseur égaré dans la savane de Buyok", "L'épouse du chef, que Kamba aimait"]$q$::jsonb, $q$["The only daughter of Kamba, a runaway slave", "The war chief who condemned Kamba", "A hunter lost in the Buyok savanna", "The chief's wife, whom Kamba loved"]$q$::jsonb, 0, $q$Selon la voix gunu, Kamba, esclave condamné pour avoir aimé la femme de son maître, fuit avec Molela au-delà de la Sanaga. Leur fille unique, Ombono, sera la mère de cinq fondateurs.$q$, $q$In the Gunu voice, Kamba, a slave condemned for loving his master's wife, flees with Molela across the Sanaga. Their only daughter, Ombono, becomes the mother of five founders.$q$),
  ('mythe', 'mythe-enfants-ombono-mbam', 4, $q$Dans le récit banen publié par Idelette Dugast, pourquoi les fils de Bayessek se séparent-ils ?$q$, $q$In the Banen story published by Idelette Dugast, why do Bayessek's sons part ways?$q$, $q$["Ils se disputent la montagne de leur père", "Le serpent-pont les coupe en deux groupes", "Seul Munen a reçu un coq cuit au partage", "Leur père les chasse après une mauvaise récolte"]$q$::jsonb, $q$["They fight over their father's mountain", "The serpent bridge cuts them into two groups", "Only Munen was given a cooked cockerel", "Their father drives them out after a bad harvest"]$q$::jsonb, 2, $q$Dans ce récit banen, qui ne passe pas par Ombono, seul Munen reçoit un coq : ses frères se fâchent et se séparent. Chez les Banen, le coq est l'animal de la justice et désignait l'héritier.$q$, $q$In this Banen story, which does not go through Ombono, only Munen gets a cockerel: his brothers grow angry and part. Among the Banen, the cockerel is the animal of justice and marked the heir.$q$),
  ('mythe', 'mythe-enfants-ombono-mbam', 5, $q$Chez les Bafia, à quoi sert le Dôm, le rite funéraire décrit par le patriarche Mouté à Bidias ?$q$, $q$Among the Bafia, what is the Dôm, the funeral rite described by patriarch Mouté à Bidias, for?$q$, $q$["À choisir le nouveau chef du village", "À demander pardon aux ancêtres du fleuve", "À partager l'héritage entre les fils aînés", "À réunir tous les descendants d'un ancêtre"]$q$::jsonb, $q$["To choose the village's new chief", "To ask forgiveness of the river ancestors", "To share the inheritance among the eldest sons", "To gather all the descendants of an ancestor"]$q$::jsonb, 3, $q$Le Dôm rassemble les descendants d'un ancêtre « afin que tous se connaissent », car « on reste frères et sœurs jusqu'à la septième génération ». Il fait pour une famille ce que le récit d'Ombono fait pour le Mbam.$q$, $q$The Dôm gathers an ancestor's descendants "so that all may know one another", for "we remain brothers and sisters until the seventh generation". It does for a family what Ombono's story does for the Mbam.$q$);
insert into public.quiz_questions
  (type_contenu, slug, ordre, question_fr, question_en, choix_fr, choix_en, bonne_reponse, explication_fr, explication_en)
values
  ('mythe', 'mythe-ti-kala-tikar', 1, $q$D'après la légende, d'où viendrait le nom « Tikar » ?$q$, $q$According to the legend, where does the name "Tikar" come from?$q$, $q$["Du nom d'un grand arbre au bord du Mbam", "D'un cri de victoire lancé contre les Peuls", "De « ti kala », « sors d'ici », un ordre de rejet en mbum", "Du nom d'une rivière du plateau de l'Adamaoua"]$q$::jsonb, $q$["From the name of a great tree on the banks of the Mbam", "From a victory cry raised against the Fulani", "From \"ti kala\", \"get out of here\", an order of rejection in Mbum", "From the name of a river on the Adamawa plateau"]$q$::jsonb, 2, $q$Selon la tradition recueillie par Wang Sonne, le Bélaka chassa son fils Klong par ces mots. Le peuple a fait de l'injure son nom. Les chercheurs, eux, proposent d'autres origines.$q$, $q$In the tradition recorded by Wang Sonne, the Belaka drove out his son Klong with these words. The people made the insult their name. Scholars, for their part, suggest other origins.$q$),
  ('mythe', 'mythe-ti-kala-tikar', 2, $q$Dans la version de Wang Sonne, pourquoi le Bélaka écarte-t-il son fils Klong ?$q$, $q$In Wang Sonne's version, why does the Belaka cast out his son Klong?$q$, $q$["Des épouses jalouses l'accusent d'une liaison avec l'une d'elles", "Il a perdu le bâton de commandement de son père", "Il n'a pas su faire tomber la pluie pendant la sécheresse", "Il a refusé de régner sept ans puis de mourir"]$q$::jsonb, $q$["Jealous wives accuse him of an affair with one of them", "He has lost his father's staff of office", "He failed to make the rain fall during the drought", "He refused to reign for seven years and then die"]$q$::jsonb, 0, $q$Selon cette version, des épouses du Bélaka, voyant que Klong pourrait succéder à son père, firent courir une rumeur. Le père la crut. Chez Beemster, le prince est seulement « accusé ».$q$, $q$In this version, some of the Belaka's wives, seeing that Klong might succeed his father, spread a rumour. The father believed it. In Beemster's version, the prince is only "accused".$q$),
  ('mythe', 'mythe-ti-kala-tikar', 3, $q$Selon les Tikar du Mbam, pourquoi Nchare, futur fondateur du royaume bamoun, se sépare-t-il de Mbe ?$q$, $q$According to the Tikar of the Mbam, why does Nchare, future founder of the Bamum kingdom, part from Mbe?$q$, $q$["Il gagne une course autour d'une pierre", "Il brise la barque de ses frères sur le fleuve", "Il est chassé par son frère cadet Gwatou", "Envoyé chercher le bâton perdu, il s'égare"]$q$::jsonb, $q$["He wins a race around a stone", "He breaks his brothers' boat on the river", "He is driven out by his younger brother Gwatou", "Sent to find the lost staff, he loses his way"]$q$::jsonb, 3, $q$Dans la version de Nditam, Mbe, l'aîné, perd son bâton de commandement et envoie Nchare le chercher. Nchare s'égare et fonde le royaume bamoun. À Foumban, on raconte autrement.$q$, $q$In the Nditam version, Mbe, the elder, loses his staff of office and sends Nchare to find it. Nchare loses his way and founds the Bamum kingdom. Foumban tells it differently.$q$),
  ('mythe', 'mythe-ti-kala-tikar', 4, $q$Selon Wang Sonne, que veut dire « Ndè ntè », d'où viendrait le nom de Nditam ?$q$, $q$According to Wang Sonne, what does "Ndè ntè", the supposed origin of the name Nditam, mean?$q$, $q$["« La montagne de pierre »", "« Cette terre est agréable, je suis à l'aise ici »", "« Les aubergines fraîches »", "« Le fils qui a perdu son bâton »"]$q$::jsonb, $q$["\"The mountain of stone\"", "\"This land is pleasant, I am at ease here\"", "\"The fresh aubergines\"", "\"The son who lost his staff\""]$q$::jsonb, 1, $q$D'après la tradition, Mbe et les siens le dirent quand des singes les saluèrent de cris aimables. C'est un mot balom, la langue des gens que Mbe avait repoussés.$q$, $q$According to tradition, Mbe and his people said it when monkeys greeted them with friendly cries. It is a Balom word, the language of the people Mbe had driven away.$q$),
  ('mythe', 'mythe-ti-kala-tikar', 5, $q$Le 12 avril 1964 à Bankim, sur quoi le sultan des Bamoun et le Fon de Nso sont-ils d'abord assis ?$q$, $q$On 12 April 1964 in Bankim, what are the Sultan of the Bamum and the Fon of Nso seated on at first?$q$, $q$["Sur des peaux de panthère", "Sur des chaises, comme leur hôte", "Sur des pierres", "Sur des nattes de raphia"]$q$::jsonb, $q$["On leopard skins", "On chairs, like their host", "On stones", "On raffia mats"]$q$::jsonb, 2, $q$Le chef tikar, lui, est sur une chaise : « vous n'êtes que les fils du Roi ». Puis il leur fait donner des chaises : « Vous êtes maintenant Rois. » Le mythe dit encore qui est l'aîné.$q$, $q$The Tikar chief sits on a chair: "you are only the sons of the King". Then he has chairs brought for them: "You are now Kings." The myth still says who is the elder.$q$),
  ('mythe', 'mythe-ndzana-nga-zogo-eton', 1, $q$Dans l'épopée eton, de qui Ndzana Nga Zogo porte-t-il le nom ?$q$, $q$In the Eton epic, whose name does Ndzana Nga Zogo bear?$q$, $q$["De son père, Ossongo", "De sa mère", "De son clan, les Benyagda", "De la rivière Lékié"]$q$::jsonb, $q$["His father's, Ossongo", "His mother's", "His clan's, the Benyagda", "The Lékié river's"]$q$::jsonb, 1, $q$Nga Zogo est le nom de sa mère, une entorse à la transmission habituelle des noms. Toute l'épopée est faite de femmes qui sauvent, qui lient, qui réclament.$q$, $q$Nga Zogo is his mother's name, a break with the usual way names are handed down. The whole epic is made of women who save, who bind, who come to claim.$q$),
  ('mythe', 'mythe-ndzana-nga-zogo-eton', 2, $q$Selon l'épopée, pourquoi la morte Abomo revient-elle trouver Ndzana ?$q$, $q$According to the epic, why does the dead Abomo come back to find Ndzana?$q$, $q$["Pour le prévenir que son mari le cherche", "Pour qu'il épouse sa jeune sœur", "Pour réclamer le vin de palme promis", "Il a trahi leur pacte : elle réclame sa bague"]$q$::jsonb, $q$["To warn him that her husband is looking for him", "So that he will marry her younger sister", "To claim the palm wine he promised", "He has betrayed their pact: she claims her ring"]$q$::jsonb, 3, $q$Ndzana avait juré de mourir avec elle, mais il connut d'autres femmes avant même qu'on l'enterre. Dans la version chantée par Pantaléon, la morte revient en chantant : « Qu'as-tu fait du pacte ? »$q$, $q$Ndzana had sworn to die with her, but he went with other women before she was even buried. In the version sung by Pantaléon, the dead woman returns singing: "What have you done with the pact?"$q$),
  ('mythe', 'mythe-ndzana-nga-zogo-eton', 3, $q$Dans la version bulu de Sangmelima, pourquoi Dzàna ne revient-il jamais du pays des morts ?$q$, $q$In the Bulu version from Sangmelima, why does Dzàna never come back from the land of the dead?$q$, $q$["Son plat de couscous se multiplie sans fin", "Le fleuve Yom l'emporte sur le retour", "Le mari d'Angonomane le retient prisonnier", "Son chien refuse de lui montrer le chemin"]$q$::jsonb, $q$["His dish of couscous keeps multiplying", "The Yom river sweeps him away on the way back", "Angonomane's husband holds him prisoner", "His dog refuses to show him the way"]$q$::jsonb, 0, $q$Angonomane dit qu'ils partiront quand il aura fini son repas, mais la nourriture se multiplie. Les Bulu en tirent une loi : le mariage ne continue pas au pays des morts.$q$, $q$Angonomane says they will leave when he has finished his meal, but the food keeps multiplying. The Bulu draw a law from it: marriage does not continue in the land of the dead.$q$),
  ('mythe', 'mythe-ndzana-nga-zogo-eton', 4, $q$Dans la version d'Awono Ekassi, qu'est-ce qui guérit Ndzana à son retour ?$q$, $q$In Awono Ekassi's version, what heals Ndzana when he returns?$q$, $q$["Les écorces des coépouses de sa mère", "Un bain dans l'eau du fleuve Yom", "L'essié : tout le clan touche un petit caillou", "Un bouc offert sur la tombe d'Abomo"]$q$::jsonb, $q$["The barks brought by his mother's co-wives", "A bath in the water of the Yom river", "The essié: the whole clan touches a small pebble", "A goat offered on Abomo's grave"]$q$::jsonb, 2, $q$Le tam-tam appelle les Benyagda pour l'essié, la palabre curative. Cent mains touchent le caillou du guérisseur Ngandeme : la guérison vient de l'assemblée. Chez Pantaléon, Ndzana meurt.$q$, $q$The drum calls the Benyagda to the essié, the healing palaver. A hundred hands touch the healer Ngandeme's pebble: the healing comes from the assembly. In Pantaléon's version, Ndzana dies.$q$),
  ('mythe', 'mythe-ndzana-nga-zogo-eton', 5, $q$Selon le témoignage de Joseph Ndzomo-Molé, qui aurait composé la chanson de Ndzana ?$q$, $q$According to Joseph Ndzomo-Molé's testimony, who composed the song of Ndzana?$q$, $q$["Awono Ekassi, pour deux chercheurs", "Mbida Kouma, son cousin joueur de mvet", "Andjeng Etaba Pantaléon, à Paris", "Nga Zogo, sa mère, après sa guérison"]$q$::jsonb, $q$["Awono Ekassi, for two researchers", "Mbida Kouma, his cousin, a mvet player", "Andjeng Etaba Pantaléon, in Paris", "Nga Zogo, his mother, after he was healed"]$q$::jsonb, 1, $q$D'après ce témoignage, unique et non recoupé, Mbida Kouma fit un morceau d'une vraie aventure amoureuse. Ndzana, d'abord furieux, finit par danser sur sa propre légende.$q$, $q$According to this testimony, the only one and unverified, Mbida Kouma made a song from a real love affair. Ndzana, furious at first, ended up dancing to his own legend.$q$),
  ('mythe', 'mythe-elig-ekulu-baton-ngat-beti', 1, $q$Selon les traditions ewondo, qui est Essomba Nak, l'enfant de la traversée ?$q$, $q$According to Ewondo tradition, who is Essomba Nak, the child of the crossing?$q$, $q$["L'ancêtre des Etudi", "Le fils du devin Ekulu Ngonda", "Le premier chef de Ngat", "L'ancêtre des Ewondo"]$q$::jsonb, $q$["The ancestor of the Etudi", "The son of the diviner Ekulu Ngonda", "The first chief of Ngat", "The ancestor of the Ewondo"]$q$::jsonb, 3, $q$Les Ewondo tiennent Essomba Nak pour leur ancêtre. Selon la légende, de lui sont sortis des lignages qui peuplent encore les collines de Yaoundé et la forêt jusqu'à Ngomedzap.$q$, $q$The Ewondo hold Essomba Nak to be their ancestor. According to the legend, from him came lineages that still people the hills of Yaoundé and the forest as far as Ngomedzap.$q$),
  ('mythe', 'mythe-elig-ekulu-baton-ngat-beti', 2, $q$Dans la version rapportée par Laburthe-Tolra, comment Ekulu Ngonda fait-il passer la Sanaga au peuple ?$q$, $q$In the version reported by Laburthe-Tolra, how does Ekulu Ngonda take the people across the Sanaga?$q$, $q$["Sur des radeaux", "Sur le dos de deux bêtes à cornes", "Sur un pont de lianes tressées", "Sur un arc-en-ciel posé sur l'eau"]$q$::jsonb, $q$["On rafts", "On the backs of two horned beasts", "On a bridge of woven lianas", "On a rainbow laid across the water"]$q$::jsonb, 0, $q$Dans cette version, Tulasa, ancêtre des Etudi, préside la traversée, et son esclave-devin la réalise sur des radeaux, « pas question directement du tronc d'arbre magique ».$q$, $q$In this version, Tulasa, ancestor of the Etudi, presides over the crossing, and his slave-diviner carries it out on rafts, with "no direct question of the magic tree trunk".$q$),
  ('mythe', 'mythe-elig-ekulu-baton-ngat-beti', 3, $q$D'après la légende, qu'a prédit le devin Ekulu Ngonda au sujet de l'enfant ?$q$, $q$According to the legend, what did the diviner Ekulu Ngonda foretell about the child?$q$, $q$["Qu'il se noierait aux chutes", "Qu'il trahirait un jour Tulasa", "Qu'il commanderait un jour tout le pays", "Qu'il deviendrait un grand devin"]$q$::jsonb, $q$["That he would drown at the falls", "That he would one day betray Tulasa", "That he would one day command the whole land", "That he would become a great diviner"]$q$::jsonb, 2, $q$Le devin conseilla donc à Tulasa de noyer l'enfant pendant la traversée. Tulasa refusa : dans cette légende, les Ewondo doivent la vie à la clémence d'un Etudi.$q$, $q$So the diviner advised Tulasa to drown the child during the crossing. Tulasa refused: in this legend, the Ewondo owe their life to the mercy of an Etudi.$q$),
  ('mythe', 'mythe-elig-ekulu-baton-ngat-beti', 4, $q$Dans le récit du bâton de Ngat, qui devient le chef du groupe de Manga ?$q$, $q$In the tale of the staff of Ngat, who becomes the chief of Manga's group?$q$, $q$["Manga, le plus âgé du groupe", "Le jeune homme qui arrache le bâton sans effort", "Le premier qui achève le tour de la forêt", "Celui que désigne le devin du clan"]$q$::jsonb, $q$["Manga, the eldest of the group", "The young man who pulls out the staff without effort", "The first to finish going round the forest", "The one chosen by the clan's diviner"]$q$::jsonb, 1, $q$Selon Thomas Essa Ngoukou (2019), après sept jours autour de la forêt, plusieurs échouent à arracher le bâton. Un jeune homme y parvient et devient chef. Le chef de Ngat le garderait encore.$q$, $q$According to Thomas Essa Ngoukou (2019), after seven days around the forest, several people fail to pull out the staff. A young man succeeds and becomes chief. Ngat's chief is said to keep it still.$q$),
  ('mythe', 'mythe-elig-ekulu-baton-ngat-beti', 5, $q$En ewondo, que veut dire le verbe dzo, d'où vient ndzoe, le chef ?$q$, $q$In Ewondo, what does the verb dzo, from which ndzoe, the chief, comes, mean?$q$, $q$["Porter, soulever", "Protéger, garder", "Marcher devant", "Dire, parler"]$q$::jsonb, $q$["To carry, to lift", "To protect, to guard", "To walk in front", "To say, to speak"]$q$::jsonb, 3, $q$Selon la thèse de Bolo Mbala, le chef est celui qui « a la première et la dernière parole ». Chez les Beti, commander, c'est d'abord parler : le bâton est la parole du chef rendue visible.$q$, $q$According to Bolo Mbala's doctorate, the chief is the one who "has the first and the last word". Among the Beti, to command is first to speak: the staff is the chief's word made visible.$q$);
